21	import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
22	import { execSync, spawnSync } from "node:child_process";
23	import { join } from "node:path";
24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
25	import { buildGitEnv } from "../git-env.js";
26	import { curlJson } from "../utils/curl-json.js";
27	import { markPrReadyForReview } from "../utils/github-graphql.js";
28	import {
29	  featuresRoot,
30	  featureBranchName,
31	  statusYamlAbsPath,
32	  statusYamlRelPath,
33	} from "../paths.js";
34	
35	// ── Types ─────────────────────────────────────────────────────────────────────
36	
37	export interface HandleFeatureDoneOpts {
38	  workspaceRoot: string;
39	  githubToken: string;
40	  gitAuthorEmail: string;
41	  gitAuthorName?: string;
42	  sshKeyPath?: string;
43	  emit: (event: Record<string, unknown>) => void;
44	}
45	
46	interface ImplFeaturePr {
47	  repo: string;
48	  url: string;
49	  status: "open" | "merged";
50	}
51	
52	interface StatusYaml {
53	  feature_status?: string;
54	  current_stage?: string;
55	  handoff_pr_url?: string | null;
56	  impl_feature_prs?: ImplFeaturePr[];
57	  workspace_feature_pr_url?: string | null;
58	  [key: string]: unknown;
59	}
60	
61	interface GitHubPr {
62	  merged_at: string | null;
63	  state: string;
64	  draft: boolean;
65	  mergeable: boolean | null;
66	  [key: string]: unknown;
67	}
68	
69	// ── Helpers ───────────────────────────────────────────────────────────────────
70	
71	function listFeatureIds(workspaceRoot: string): string[] {
72	  const docsPath = featuresRoot(workspaceRoot);
73	  if (!existsSync(docsPath)) return [];
74	  try {
75	    return readdirSync(docsPath, { withFileTypes: true })
76	      .filter((e) => e.isDirectory())
77	      .map((e) => e.name);
78	  } catch {
79	    return [];
80	  }
81	}
