83	function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
84	  // feature_status: in_handoff is committed to the feature branch only — the
85	  // local FS is reset to origin/main by syncRepo each poll cycle. Read from
86	  // the remote feature branch first (same fix as loadFeatureTasks in T5).
87	  const branchName = featureBranchName(featureId);
88	  const relPath = statusYamlRelPath(featureId);
89	  try {
90	    const raw = execSync(
91	      `git -C "${workspaceRoot}" show "origin/${branchName}:${relPath}"`,
92	      { encoding: "utf-8", stdio: "pipe" },
93	    ) as string;
94	    if (raw) {
95	      const parsed = parseYaml(raw) as StatusYaml | undefined;
96	      if (parsed && typeof parsed === "object") return parsed;
97	    }
98	  } catch { /* fall back to local FS */ }
99	
100	  // Local FS fallback (pre-feature-branch features, or when git show fails)
101	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
102	  if (!existsSync(statusPath)) return {};
103	  try {
104	    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
105	  } catch {
106	    return {};
107	  }
108	}
