110	/**
111	 * Parse a GitHub PR URL into owner/repo/number. Returns null on bad input.
112	 */
113	function parsePrUrl(url: string): { owner: string; repo: string; pullNumber: number } | null {
114	  const match = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
115	  if (!match) return null;
116	  return {
117	    owner: match[1],
118	    repo: match[2],
119	    pullNumber: parseInt(match[3], 10),
120	  };
121	}
122	
123	/**
124	 * Check whether a single GitHub PR is merged via the REST API.
125	 * Returns true if merged, false if not yet merged, throws on API error.
126	 */
127	export function isPrMerged(url: string, githubToken: string): boolean {
128	  const coords = parsePrUrl(url);
129	  if (!coords) throw new Error(`Cannot parse PR URL: ${url}`);
130	
131	  const { owner, repo, pullNumber } = coords;
132	  const apiUrl = `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}`;
133	  const pr = curlJson([
134	    "-s",
135	    "-H", `Authorization: token ${githubToken}`,
136	    "-H", "Accept: application/vnd.github+json",
137	    apiUrl,
138	  ]) as GitHubPr;
139	
140	  return pr.merged_at !== null && pr.merged_at !== undefined;
141	}
