143	/**
144	 * Attempt to squash-merge the workspace feature PR (feature/{id} → main).
145	 * Emits one of: workspace_feature_pr_merged, workspace_feature_pr_merge_failed,
146	 * workspace_feature_pr_not_mergeable, workspace_feature_pr_url_missing.
147	 */
148	function autoMergeWorkspacePr(
149	  prUrl: string | null | undefined,
150	  githubToken: string,
151	  featureId: string,
152	  emit: (event: Record<string, unknown>) => void,
153	): void {
154	  if (!prUrl) {
155	    emit({ type: "workspace_feature_pr_url_missing", feature_id: featureId });
156	    return;
157	  }
158	
159	  const coords = parsePrUrl(prUrl);
160	  if (!coords) {
161	    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: "Cannot parse PR URL" });
162	    return;
163	  }
164	
165	  const { owner, repo, pullNumber } = coords;
166	
167	  // Check mergeability before attempting merge
168	  let pr: GitHubPr;
169	  try {
170	    pr = curlJson([
171	      "-s",
172	      "-H", `Authorization: token ${githubToken}`,
173	      "-H", "Accept: application/vnd.github+json",
174	      `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}`,
175	    ]) as GitHubPr;
176	  } catch (e) {
177	    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: String(e) });
178	    return;
179	  }
180	
181	  // mergeable: false → conflicting; skip and let operator resolve
182	  if (pr.mergeable === false) {
183	    emit({ type: "workspace_feature_pr_not_mergeable", feature_id: featureId, pr_url: prUrl });
184	    return;
185	  }
186	
187	  // Draft PRs cannot be merged — promote to ready-for-review first.
188	  if (pr.draft) {
189	    const promoted = markPrReadyForReview(prUrl, githubToken);
190	    if (!promoted) {
191	      emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: "PR is a draft and could not be promoted to ready-for-review" });
192	      return;
193	    }
194	    emit({ type: "workspace_feature_pr_undrafted", feature_id: featureId, pr_url: prUrl });
195	  }
196	
197	  // mergeable: true or null (GitHub still computing) → attempt merge
198	  try {
199	    const mergeResult = curlJson([
200	      "-s", "-X", "PUT",
201	      "-H", `Authorization: token ${githubToken}`,
202	      "-H", "Accept: application/vnd.github+json",
203	      "-H", "Content-Type: application/json",
204	      "-d", JSON.stringify({ merge_method: "squash" }),
205	      `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}/merge`,
206	    ]) as { merged?: boolean; message?: string };
207	
208	    if (mergeResult.merged === true) {
209	      emit({ type: "workspace_feature_pr_merged", feature_id: featureId, pr_url: prUrl });
210	    } else {
211	      emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: mergeResult.message ?? "unknown" });
212	    }
213	  } catch (e) {
214	    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: String(e) });
215	  }
216	}
217	
218	// ── Main export ───────────────────────────────────────────────────────────────
219	
220	/**
221	 * Check all `in_handoff` features in the workspace and transition any that
222	 * have all PRs merged to `feature_status: done`.
223	 */
224	export async function handleFeatureDone(opts: HandleFeatureDoneOpts): Promise<void> {
225	  const {
226	    workspaceRoot,
227	    githubToken,
228	    gitAuthorEmail,
229	    gitAuthorName = gitAuthorEmail,
230	    sshKeyPath,
231	    emit,
232	  } = opts;
233	
234	  if (!githubToken) {
235	    emit({ type: "feature_done_check_skipped", reason: "no_github_token" });
236	    return;
237	  }
238	
239	  const featureIds = listFeatureIds(workspaceRoot);
240	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
241	
242	  for (const featureId of featureIds) {
243	    const statusYaml = readStatusYaml(workspaceRoot, featureId);
244	
245	    if (statusYaml.feature_status !== "in_handoff") continue;
246	
247	    const handoffPrUrl = statusYaml.handoff_pr_url ?? null;
248	    const implFeaturePrs: ImplFeaturePr[] = Array.isArray(statusYaml.impl_feature_prs)
249	      ? statusYaml.impl_feature_prs
250	      : [];
251	
252	    // Determine which PRs to check
253	    const implPrsAbsentOrEmpty = implFeaturePrs.length === 0;
254	    if (implPrsAbsentOrEmpty) {
255	      emit({ type: "impl_feature_prs_missing", feature_id: featureId });
256	    }
257	
258	    if (!handoffPrUrl) {
259	      emit({ type: "feature_done_check_skipped", feature_id: featureId, reason: "no_handoff_pr_url" });
260	      continue;
261	    }
262	
263	    // Check each PR for merge state
264	    let allMerged = true;
265	    const updatedImplPrs = [...implFeaturePrs];
266	
267	    // Check handoff (management repo) PR
268	    try {
269	      const handoffMerged = isPrMerged(handoffPrUrl, githubToken);
270	      if (!handoffMerged) {
271	        allMerged = false;
272	      }
273	    } catch (e) {
274	      emit({ type: "feature_done_check_failed", feature_id: featureId, pr_url: handoffPrUrl, details: String(e) });
275	      continue;
276	    }
277	
278	    // Check impl repo PRs (unless absent — already handled above)
279	    if (!implPrsAbsentOrEmpty) {
280	      for (let i = 0; i < updatedImplPrs.length; i++) {
281	        const entry = updatedImplPrs[i];
282	        try {
283	          const merged = isPrMerged(entry.url, githubToken);
284	          if (merged) {
285	            updatedImplPrs[i] = { ...entry, status: "merged" };
286	          } else {
287	            allMerged = false;
288	          }
289	        } catch (e) {
290	          emit({ type: "feature_done_check_failed", feature_id: featureId, pr_url: entry.url, details: String(e) });
291	          allMerged = false;
292	          break;
293	        }
294	      }
295	    }
296	
297	    if (!allMerged) continue;
298	
299	    // All PRs merged — transition to done
300	    try {
301	      // Checkout feature branch to commit status.yaml update
302	      const featureBranch = featureBranchName(featureId);
303	      execSync(`git fetch origin`, { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 60_000 });
304	      execSync(
305	        `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
306	        { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
307	      );
308	
309	      // Re-read status.yaml after checkout to get latest state
310	      const freshStatus = readStatusYaml(workspaceRoot, featureId);
311	
312	      // Idempotency guard — already done
313	      if (freshStatus.feature_status === "done") {
314	        emit({ type: "feature_done_already", feature_id: featureId });
315	        continue;
316	      }
317	
318	      // Write updated status.yaml
319	      freshStatus.feature_status = "done";
320	      freshStatus.current_stage = "done";
321	      if (!implPrsAbsentOrEmpty) {
322	        freshStatus.impl_feature_prs = updatedImplPrs;
323	      }
324	
325	      const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
326	      writeFileSync(statusPath, yamlStringify(freshStatus), "utf-8");
327	
328	      const statusRel = statusYamlRelPath(featureId);
329	      execSync(`git add "${statusRel}"`, { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 10_000 });
330	      try {
331	        execSync(
332	          `git commit -m "chore(${featureId}): feature_status → done — all PRs merged"`,
333	          { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
334	        );
335	      } catch (e) {
336	        const stderr = (e as { stderr?: string }).stderr ?? String(e);
337	        if (!stderr.includes("nothing to commit")) throw e;
338	      }
339	
340	      const pushResult = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
341	        env,
342	        encoding: "utf-8",
343	      });
344	      if (pushResult.status !== 0) {
345	        emit({
346	          type: "feature_done_push_failed",
347	          feature_id: featureId,
348	          details: pushResult.stderr,
349	        });
350	        continue;
351	      }
352	
353	      // Auto-merge the workspace feature PR (feature/{id} → main)
354	      autoMergeWorkspacePr(freshStatus.workspace_feature_pr_url, githubToken, featureId, emit);
355	
356	      emit({ type: "feature_done", feature_id: featureId, handoff_pr_url: handoffPrUrl });
357	    } catch (e) {
358	      emit({ type: "feature_done_check_failed", feature_id: featureId, details: String(e) });
359	    }
360	  }
361	}
