/**
 * NotificationPort — the unified interface that core orchestrator logic depends on.
 *
 * Core code must never import Slack, Redis, or formatter modules directly.
 * All notification paths go through this interface.
 */

import type {
  FeatureTrigger,
  FeatureContext,
  TaskTrigger,
  TaskContext,
} from "./notification.types.js";

export interface NotificationPort {
  /** Post or update a feature-level Slack message. */
  postFeatureMessage(
    featureId: string,
    trigger: FeatureTrigger,
    context: FeatureContext,
  ): Promise<void>;

  /** Post the final feature message and clean up the feature thread mapping. */
  closeFeatureThread(featureId: string, context: FeatureContext): Promise<void>;

  /** Post or update a task-level Slack message. */
  postTaskMessage(
    featureId: string,
    taskId: string,
    trigger: TaskTrigger,
    context: TaskContext,
  ): Promise<void>;

  /** Post the final task message and clean up the task thread mapping. */
  closeTaskThread(
    featureId: string,
    taskId: string,
    context: TaskContext,
  ): Promise<void>;
}

