1	/**
2	 * ThreadedNotificationService — stateful service that composes the Slack client,
3	 * the Redis thread store, and the message formatters to provide scope-separated
4	 * Slack threading for feature and task notifications.
5	 *
6	 * All public methods emit structured events and never throw in a way that would
7	 * block workflow progression.
8	 */
9	
10	import type { SlackWebApiClient } from "../slack/slack-web-api-client.js";
11	import type { NotificationThreadStorePort } from "../ports/notification-thread-store.port.js";
12	import type {
13	  FeatureTrigger,
14	  FeatureContext,
15	  TaskTrigger,
16	  TaskContext,
17	} from "./notification.types.js";
18	import {
19	  formatFeatureTopLevel,
20	  formatFeatureReply,
21	  extractFeatureChangedFields,
22	} from "./feature-formatter.js";
23	import {
24	  formatTaskTopLevel,
25	  formatTaskReply,
26	  extractTaskChangedFields,
27	} from "./task-formatter.js";
28	
29	export interface NotificationServiceDeps {
30	  slack: SlackWebApiClient | null;
31	  store: NotificationThreadStorePort | null;
32	  workspaceId: string;
33	  emit: (event: NotificationEvent) => void;
34	}
35	
36	// ── Structured event types ─────────────────────────────────────────────────────
37	
38	export type NotificationEvent =
39	  | { type: "feature_slack_thread_created"; featureId: string; threadTs: string }
40	  | { type: "feature_slack_thread_updated"; featureId: string; threadTs: string }
41	  | { type: "feature_slack_reply_posted"; featureId: string; threadTs: string }
42	  | { type: "feature_slack_thread_deleted"; featureId: string }
43	  | { type: "feature_slack_thread_delete_failed"; featureId: string; reason: string }
44	  | { type: "task_slack_thread_created"; featureId: string; taskId: string; threadTs: string }
45	  | { type: "task_slack_thread_updated"; featureId: string; taskId: string; threadTs: string }
46	  | { type: "task_slack_reply_posted"; featureId: string; taskId: string; threadTs: string }
47	  | { type: "task_slack_thread_deleted"; featureId: string; taskId: string }
48	  | { type: "task_slack_thread_delete_failed"; featureId: string; taskId: string; reason: string }
49	  | { type: "slack_notification_skipped"; reason: string }
50	  | { type: "slack_notification_failed"; reason: string }
51	  | { type: "redis_operation_failed"; operation: string; reason: string };
52	
53	export class ThreadedNotificationService {
54	  constructor(private readonly deps: NotificationServiceDeps) {}
55	
56	  private get configured(): boolean {
57	    return this.deps.slack !== null && this.deps.store !== null;
58	  }
59	
60	  // ── Feature thread ──────────────────────────────────────────────────────────
61	
62	  /**
63	   * Ensure a feature-level Slack thread exists.
64	   * - If the Redis key already exists, reuse it.
65	   * - If absent and Slack+Redis configured, post the first message and store the ts.
66	   */
67	  async ensureFeatureThread(
68	    featureId: string,
69	    context: FeatureContext,
70	  ): Promise<string | null> {
71	    if (!this.configured) {
72	      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
73	      return null;
74	    }
75	
76	    const store = this.deps.store!;
77	    const slack = this.deps.slack!;
78	
79	    let threadTs: string | null;
80	    try {
81	      threadTs = await store.getFeatureThread(this.deps.workspaceId, featureId);
82	    } catch (err) {
83	      this.deps.emit({
84	        type: "redis_operation_failed",
85	        operation: "getFeatureThread",
86	        reason: String(err),
87	      });
88	      return null;
89	    }
90	
91	    if (threadTs) {
92	      return threadTs;
93	    }
94	
95	    // Create the feature thread
96	    const text = formatFeatureTopLevel(context);
97	    let result: { ts: string };
98	    try {
99	      result = await slack.postMessage(text);
100	    } catch (err) {
101	      this.deps.emit({
102	        type: "slack_notification_failed",
103	        reason: `chat.postMessage for feature thread: ${String(err)}`,
104	      });
105	      return null;
106	    }
107	
108	    try {
109	      await store.setFeatureThread(this.deps.workspaceId, featureId, result.ts);
110	    } catch (err) {
111	      this.deps.emit({
112	        type: "redis_operation_failed",
113	        operation: "setFeatureThread",
114	        reason: String(err),
115	      });
116	      // Return the ts anyway — message was posted, just not stored
117	    }
118	
119	    this.deps.emit({
120	      type: "feature_slack_thread_created",
121	      featureId,
122	      threadTs: result.ts,
123	    });
124	
125	    return result.ts;
126	  }
127	
128	  /**
129	   * Ensure a task-level Slack thread exists.
130	   * - If the Redis key already exists, reuse it.
131	   * - If absent and Slack+Redis configured, post the first task message and store the ts.
132	   */
133	  async ensureTaskThread(
134	    featureId: string,
135	    taskId: string,
136	    context: TaskContext,
137	  ): Promise<string | null> {
138	    if (!this.configured) {
139	      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
140	      return null;
141	    }
142	
143	    const store = this.deps.store!;
144	    const slack = this.deps.slack!;
145	
146	    let threadTs: string | null;
147	    try {
148	      threadTs = await store.getTaskThread(this.deps.workspaceId, featureId, taskId);
149	    } catch (err) {
150	      this.deps.emit({
151	        type: "redis_operation_failed",
152	        operation: "getTaskThread",
153	        reason: String(err),
154	      });
155	      return null;
156	    }
157	
158	    if (threadTs) {
159	      return threadTs;
160	    }
161	
162	    // Create the task thread as a top-level message (not in the feature thread)
163	    const text = formatTaskTopLevel(context);
164	    let result: { ts: string };
165	    try {
166	      result = await slack.postMessage(text);
167	    } catch (err) {
168	      this.deps.emit({
169	        type: "slack_notification_failed",
170	        reason: `chat.postMessage for task thread: ${String(err)}`,
171	      });
172	      return null;
173	    }
174	
175	    try {
176	      await store.setTaskThread(this.deps.workspaceId, featureId, taskId, result.ts);
177	    } catch (err) {
178	      this.deps.emit({
179	        type: "redis_operation_failed",
180	        operation: "setTaskThread",
181	        reason: String(err),
182	      });
183	      // Return the ts anyway
184	    }
185	
186	    this.deps.emit({
187	      type: "task_slack_thread_created",
188	      featureId,
189	      taskId,
190	      threadTs: result.ts,
191	    });
192	
193	    return result.ts;
194	  }
195	
196	  // ── Feature messages ────────────────────────────────────────────────────────
197	
198	  /**
199	   * Post or update a feature-level Slack message.
200	   *
201	   * - `feature_start`: creates the feature thread via ensureFeatureThread only.
202	   * - All other triggers: update top-level message via chat.update, then post a reply.
203	   */
204	  async postFeatureMessage(
205	    featureId: string,
206	    trigger: FeatureTrigger,
207	    context: FeatureContext,
208	  ): Promise<void> {
209	    if (!this.configured) {
210	      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
211	      return;
212	    }
213	
214	    if (trigger === "feature_start") {
215	      await this.ensureFeatureThread(featureId, context);
216	      return;
217	    }
218	
