/**
 * ThreadedNotificationService — stateful service that composes the Slack client,
 * the Redis thread store, and the message formatters to provide scope-separated
 * Slack threading for feature and task notifications.
 *
 * All public methods emit structured events and never throw in a way that would
 * block workflow progression.
 */

import type { SlackWebApiClient } from "../slack/slack-web-api-client.js";
import type { NotificationThreadStorePort } from "../ports/notification-thread-store.port.js";
import type {
  FeatureTrigger,
  FeatureContext,
  TaskTrigger,
  TaskContext,
} from "./notification.types.js";
import {
  formatFeatureTopLevel,
  formatFeatureReply,
  extractFeatureChangedFields,
} from "./feature-formatter.js";
import {
  formatTaskTopLevel,
  formatTaskReply,
  extractTaskChangedFields,
} from "./task-formatter.js";

export interface NotificationServiceDeps {
  slack: SlackWebApiClient | null;
  store: NotificationThreadStorePort | null;
  workspaceId: string;
  emit: (event: NotificationEvent) => void;
}

// ── Structured event types ─────────────────────────────────────────────────────

export type NotificationEvent =
  | { type: "feature_slack_thread_created"; featureId: string; threadTs: string }
  | { type: "feature_slack_thread_updated"; featureId: string; threadTs: string }
  | { type: "feature_slack_reply_posted"; featureId: string; threadTs: string }
  | { type: "feature_slack_thread_deleted"; featureId: string }
  | { type: "feature_slack_thread_delete_failed"; featureId: string; reason: string }
  | { type: "task_slack_thread_created"; featureId: string; taskId: string; threadTs: string }
  | { type: "task_slack_thread_updated"; featureId: string; taskId: string; threadTs: string }
  | { type: "task_slack_reply_posted"; featureId: string; taskId: string; threadTs: string }
  | { type: "task_slack_thread_deleted"; featureId: string; taskId: string }
  | { type: "task_slack_thread_delete_failed"; featureId: string; taskId: string; reason: string }
  | { type: "slack_notification_skipped"; reason: string }
  | { type: "slack_notification_failed"; reason: string }
  | { type: "redis_operation_failed"; operation: string; reason: string };

export class ThreadedNotificationService {
  constructor(private readonly deps: NotificationServiceDeps) {}

  private get configured(): boolean {
    return this.deps.slack !== null && this.deps.store !== null;
  }

  // ── Feature thread ──────────────────────────────────────────────────────────

  /**
   * Ensure a feature-level Slack thread exists.
   * - If the Redis key already exists, reuse it.
   * - If absent and Slack+Redis configured, post the first message and store the ts.
   */
  async ensureFeatureThread(
    featureId: string,
    context: FeatureContext,
  ): Promise<string | null> {
    if (!this.configured) {
      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
      return null;
    }

    const store = this.deps.store!;
    const slack = this.deps.slack!;

    let threadTs: string | null;
    try {
      threadTs = await store.getFeatureThread(this.deps.workspaceId, featureId);
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "getFeatureThread",
        reason: String(err),
      });
      return null;
    }

    if (threadTs) {
      return threadTs;
    }

    // Create the feature thread
    const text = formatFeatureTopLevel(context);
    let result: { ts: string };
    try {
      result = await slack.postMessage(text);
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.postMessage for feature thread: ${String(err)}`,
      });
      return null;
    }

    try {
      await store.setFeatureThread(this.deps.workspaceId, featureId, result.ts);
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "setFeatureThread",
        reason: String(err),
      });
      // Return the ts anyway — message was posted, just not stored
    }

    this.deps.emit({
      type: "feature_slack_thread_created",
      featureId,
      threadTs: result.ts,
    });

    return result.ts;
  }

  /**
   * Ensure a task-level Slack thread exists.
   * - If the Redis key already exists, reuse it.
   * - If absent and Slack+Redis configured, post the first task message and store the ts.
   */
  async ensureTaskThread(
    featureId: string,
    taskId: string,
    context: TaskContext,
  ): Promise<string | null> {
    if (!this.configured) {
      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
      return null;
    }

    const store = this.deps.store!;
    const slack = this.deps.slack!;

    let threadTs: string | null;
    try {
      threadTs = await store.getTaskThread(this.deps.workspaceId, featureId, taskId);
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "getTaskThread",
        reason: String(err),
      });
      return null;
    }

    if (threadTs) {
      return threadTs;
    }

    // Create the task thread as a top-level message (not in the feature thread)
    const text = formatTaskTopLevel(context);
    let result: { ts: string };
    try {
      result = await slack.postMessage(text);
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.postMessage for task thread: ${String(err)}`,
      });
      return null;
    }

    try {
      await store.setTaskThread(this.deps.workspaceId, featureId, taskId, result.ts);
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "setTaskThread",
        reason: String(err),
      });
      // Return the ts anyway
    }

    this.deps.emit({
      type: "task_slack_thread_created",
      featureId,
      taskId,
      threadTs: result.ts,
    });

    return result.ts;
  }

  // ── Feature messages ────────────────────────────────────────────────────────

  /**
   * Post or update a feature-level Slack message.
   *
   * - `feature_start`: creates the feature thread via ensureFeatureThread only.
   * - All other triggers: update top-level message via chat.update, then post a reply.
   */
  async postFeatureMessage(
    featureId: string,
    trigger: FeatureTrigger,
    context: FeatureContext,
  ): Promise<void> {
    if (!this.configured) {
      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
      return;
    }

    if (trigger === "feature_start") {
      await this.ensureFeatureThread(featureId, context);
      return;
    }

    // For subsequent triggers: lazily ensure thread, then update + reply
    let threadTs: string | null;
    try {
      threadTs = await this.deps.store!.getFeatureThread(this.deps.workspaceId, featureId);
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "getFeatureThread",
        reason: String(err),
      });
      return;
    }

    if (!threadTs) {
      // Lazy creation
      threadTs = await this.ensureFeatureThread(featureId, context);
      if (!threadTs) return;
      // Top-level was just created — no update needed, only return
      return;
    }

    // Update the top-level message in place
    const topLevelText = formatFeatureTopLevel(context);
    try {
      await this.deps.slack!.updateMessage(threadTs, topLevelText);
      this.deps.emit({
        type: "feature_slack_thread_updated",
        featureId,
        threadTs,
      });
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.update for feature top-level: ${String(err)}`,
      });
      // Continue to try posting the reply
    }

    // Post a reply with only the changed fields
    const changed = extractFeatureChangedFields({}, context);
    // Include the lastUpdatedAt in the changed reply
    const replyText = formatFeatureReply(trigger, {
      ...changed,
      lastUpdatedAt: context.lastUpdatedAt ?? null,
    });
    try {
      await this.deps.slack!.postMessage(replyText, { threadTs });
      this.deps.emit({
        type: "feature_slack_reply_posted",
        featureId,
        threadTs,
      });
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.postMessage reply for feature thread: ${String(err)}`,
      });
    }
  }

  // ── Task messages ───────────────────────────────────────────────────────────

  /**
   * Post or update a task-level Slack message.
   *
   * - `task_start`: creates the task thread via ensureTaskThread only.
   * - All other triggers: update top-level message via chat.update, then post a reply.
   *
   * Task messages NEVER fall back to the feature thread.
   */
  async postTaskMessage(
    featureId: string,
    taskId: string,
    trigger: TaskTrigger,
    context: TaskContext,
  ): Promise<void> {
    if (!this.configured) {
      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
      return;
    }

    if (trigger === "task_start") {
      await this.ensureTaskThread(featureId, taskId, context);
      return;
    }

    // For subsequent triggers: lazily ensure thread, then update + reply
    let threadTs: string | null;
    try {
      threadTs = await this.deps.store!.getTaskThread(
        this.deps.workspaceId,
        featureId,
        taskId,
      );
    } catch (err) {
      this.deps.emit({
        type: "redis_operation_failed",
        operation: "getTaskThread",
        reason: String(err),
      });
      return;
    }

    if (!threadTs) {
      // Lazy creation — never falls back to feature thread
      threadTs = await this.ensureTaskThread(featureId, taskId, context);
      if (!threadTs) return;
      // Top-level was just created — no update needed
      return;
    }

    // Update the top-level message in place
    const topLevelText = formatTaskTopLevel(context);
    try {
      await this.deps.slack!.updateMessage(threadTs, topLevelText);
      this.deps.emit({
        type: "task_slack_thread_updated",
        featureId,
        taskId,
        threadTs,
      });
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.update for task top-level: ${String(err)}`,
      });
      // Continue to try posting the reply
    }

    // Post a reply with only the changed fields
    const changed = extractTaskChangedFields({}, context);
    const replyText = formatTaskReply(trigger, {
      ...changed,
      lastUpdatedAt: context.lastUpdatedAt ?? null,
    });
    try {
      await this.deps.slack!.postMessage(replyText, { threadTs });
      this.deps.emit({
        type: "task_slack_reply_posted",
        featureId,
        taskId,
        threadTs,
      });
    } catch (err) {
      this.deps.emit({
        type: "slack_notification_failed",
        reason: `chat.postMessage reply for task thread: ${String(err)}`,
      });
    }
  }

  // ── Close methods ───────────────────────────────────────────────────────────

  /**
   * Post the final feature completion message, then delete the Redis feature key.
   * Delete failure emits a structured event but does not block completion.
   */
  async closeFeatureThread(
    featureId: string,
    context: FeatureContext,
  ): Promise<void> {
    await this.postFeatureMessage(featureId, "feature_completed", context);

    if (!this.deps.store) return;

    try {
      await this.deps.store.deleteFeatureThread(this.deps.workspaceId, featureId);
      this.deps.emit({ type: "feature_slack_thread_deleted", featureId });
    } catch (err) {
      this.deps.emit({
        type: "feature_slack_thread_delete_failed",
        featureId,
        reason: String(err),
      });
    }

    // Best-effort delete all remaining task thread keys for this feature
    try {
      await this.deps.store.deleteAllTaskThreads(this.deps.workspaceId, featureId);
    } catch {
      // Best-effort only — do not emit additional failure events here
    }
  }

  /**
   * Post the final task completion message, then delete the Redis task key.
   * Delete failure emits a structured event but does not block task transition.
   */
  async closeTaskThread(
    featureId: string,
    taskId: string,
    context: TaskContext,
  ): Promise<void> {
    await this.postTaskMessage(featureId, taskId, "task_completed", context);

    if (!this.deps.store) return;

    try {
      await this.deps.store.deleteTaskThread(this.deps.workspaceId, featureId, taskId);
      this.deps.emit({ type: "task_slack_thread_deleted", featureId, taskId });
    } catch (err) {
      this.deps.emit({
        type: "task_slack_thread_delete_failed",
        featureId,
        taskId,
        reason: String(err),
      });
    }
  }
}

