/**
 * Feature-Tasks-Done checker — polls for features where all tasks are done
 * and fires the Handoff Trigger.
 *
 * Runs on every poll cycle (after handleMergedPrs). Reads task YAMLs from
 * origin/<featureBranch> — the authoritative multi-task view — rather than
 * from the local FS of a single task branch.
 *
 * A feature is eligible when:
 *   - feature_status is not already "in_handoff", "done", or "cancelled"
 *   - handoff_pr_url is null (idempotent guard)
 *   - every T*.yaml on origin/<featureBranch> has status "done" or "cancelled"
 *   - at least one task is "done" (pure-cancelled features are skipped)
 *
 * This replaces the inline checkAllTasksDone + fireHandoffTrigger calls that
 * previously lived inside handle-merged-prs and dispatch-review-result, both
 * of which read from the local task-branch FS and could fire too early when
 * sibling task YAMLs were not yet present on that branch.
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { execSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import type { Task } from "../types/task.js";
import { featuresRoot, featureBranchName, statusYamlRelPath, TASKS_DIR } from "../paths.js";
import { buildGitEnv } from "../git-env.js";
import { fireHandoffTrigger } from "../handoff/handoff-trigger.js";
import { parseManagementRepoCoords } from "../config/workspace-config.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CheckFeatureTasksDoneOpts {
  workspaceRoot: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

interface StatusYaml {
  feature_status?: string;
  feature_branch?: string | null;
  handoff_pr_url?: string | null;
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

