const handoffsDir = join(featuresRoot(workspaceRoot), featureId, "handoffs");
const handoffPath = join(handoffsDir, "handoff.md");
const handoffRelPath = join("docs", "features", featureId, "handoffs", "handoff.md");

try {
  mkdirSync(handoffsDir, { recursive: true });
