import { createClient, type RedisClientType } from "redis";
import type { NotificationThreadStorePort } from "../ports/notification-thread-store.port.js";

function featureKey(workspaceId: string, featureId: string): string {
  return `slack:feature_thread:${workspaceId}:${featureId}`;
}

function taskKey(workspaceId: string, featureId: string, taskId: string): string {
  return `slack:task_thread:${workspaceId}:${featureId}:${taskId}`;
}

function taskKeyPrefix(workspaceId: string, featureId: string): string {
  return `slack:task_thread:${workspaceId}:${featureId}:`;
}

export interface RedisThreadStoreError {
  type: "redis_thread_store_error";
  operation: string;
  key: string;
  reason: string;
}

export class RedisThreadStore implements NotificationThreadStorePort {
  private client: RedisClientType;
  private connected = false;

  constructor(redisUrl: string) {
    this.client = createClient({ url: redisUrl }) as RedisClientType;
  }

  private async ensureConnected(): Promise<void> {
    if (!this.connected) {
      await this.client.connect();
      this.connected = true;
    }
  }

  async getFeatureThread(workspaceId: string, featureId: string): Promise<string | null> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    return this.client.get(key);
  }

  async setFeatureThread(workspaceId: string, featureId: string, threadTs: string): Promise<void> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    await this.client.set(key, threadTs);
  }

  async deleteFeatureThread(workspaceId: string, featureId: string): Promise<void> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    await this.client.del(key);
  }

  async getTaskThread(workspaceId: string, featureId: string, taskId: string): Promise<string | null> {
    await this.ensureConnected();
    const key = taskKey(workspaceId, featureId, taskId);
    return this.client.get(key);
  }

  async setTaskThread(workspaceId: string, featureId: string, taskId: string, threadTs: string): Promise<void> {
    await this.ensureConnected();
    const key = taskKey(workspaceId, featureId, taskId);
    await this.client.set(key, threadTs);
  }

  async deleteTaskThread(workspaceId: string, featureId: string, taskId: string): Promise<void> {
    await this.ensureConnected();
    const key = taskKey(workspaceId, featureId, taskId);
    await this.client.del(key);
  }

  async deleteAllTaskThreads(workspaceId: string, featureId: string): Promise<void> {
    await this.ensureConnected();
    const prefix = taskKeyPrefix(workspaceId, featureId);
    for await (const key of this.client.scanIterator({ MATCH: `${prefix}*`, COUNT: 100 })) {
      await this.client.del(key);
    }
  }

  async disconnect(): Promise<void> {
    if (this.connected) {
      await this.client.disconnect();
      this.connected = false;
    }
  }
}

/**
 * Parse `REDIS_URL` from the environment.
 * Returns the URL string if set, or null if absent.
 * Never throws — missing REDIS_URL is treated as threading-disabled.
 */
export function parseRedisUrl(): string | null {
  return process.env["REDIS_URL"] ?? null;
}

/**
 * Build a RedisThreadStore from env, or return null if REDIS_URL is absent.
 * The store is not connected until the first operation.
 */
export function buildRedisThreadStore(): RedisThreadStore | null {
  const url = parseRedisUrl();
  if (!url) return null;
  return new RedisThreadStore(url);
}

