/**
 * Feature Done Watcher (T4).
 *
 * Poll step that automatically transitions `feature_status` from `in_handoff`
 * to `done` when all feature PRs are merged.
 *
 * Steps per feature:
 *   1. Read status.yaml — skip if feature_status !== "in_handoff".
 *   2. Read handoff_pr_url and impl_feature_prs from status.yaml.
 *   3. Call GitHub REST API to check merge state for each PR.
 *   4. All PRs merged →
 *      a. Checkout feature/{id} (still alive); write feature_status: done +
 *         current_stage: done; commit + push to feature/{id}.
 *      b. Auto-merge workspace_feature_pr_url (squash) if present and mergeable.
 *      c. Emit feature_done.
 *   5. impl_feature_prs absent or empty → check only handoff_pr_url;
 *      emit impl_feature_prs_missing.
 *   6. GitHub API error → emit feature_done_check_failed; continue (non-fatal).
 */

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import { curlJson } from "../utils/curl-json.js";
import { markPrReadyForReview } from "../utils/github-graphql.js";
import {
  featuresRoot,
  featureBranchName,
  statusYamlAbsPath,
  statusYamlRelPath,
  TASKS_DIR,
} from "../paths.js";
import type { NotificationPort } from "../notifications/notification.port.js";
import type { FeatureContext } from "../notifications/notification.types.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface HandleFeatureDoneOpts {
  workspaceRoot: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
  notificationPort?: NotificationPort | null;
}

interface ImplFeaturePr {
  repo: string;
  url: string;
  status: "open" | "merged";
}

interface StatusYaml {
  feature_status?: string;
  current_stage?: string;
  title?: string;
  handoff_pr_url?: string | null;
  impl_feature_prs?: ImplFeaturePr[];
  workspace_feature_pr_url?: string | null;
  [key: string]: unknown;
}

interface GitHubPr {
  merged_at: string | null;
  state: string;
  draft: boolean;
  mergeable: boolean | null;
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const docsPath = featuresRoot(workspaceRoot);
  if (!existsSync(docsPath)) return [];
  try {
    return readdirSync(docsPath, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
  // feature_status: in_handoff is committed to the feature branch only — the
  // local FS is reset to origin/main by syncRepo each poll cycle. Read from
  // the remote feature branch first (same fix as loadFeatureTasks in T5).
  const branchName = featureBranchName(featureId);
  const relPath = statusYamlRelPath(featureId);
  try {
    const raw = execSync(
      `git -C "${workspaceRoot}" show "origin/${branchName}:${relPath}"`,
      { encoding: "utf-8", stdio: "pipe" },
    ) as string;
    if (raw) {
      const parsed = parseYaml(raw) as StatusYaml | undefined;
      if (parsed && typeof parsed === "object") return parsed;
    }
  } catch { /* fall back to local FS */ }

  // Local FS fallback (pre-feature-branch features, or when git show fails)
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  if (!existsSync(statusPath)) return {};
  try {
    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
  } catch {
    return {};
  }
}

/**
 * Parse a GitHub PR URL into owner/repo/number. Returns null on bad input.
 */
function parsePrUrl(url: string): { owner: string; repo: string; pullNumber: number } | null {
  const match = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
  if (!match) return null;
  return {
    owner: match[1],
    repo: match[2],
    pullNumber: parseInt(match[3], 10),
  };
}

/**
 * Check whether a single GitHub PR is merged via the REST API.
 * Returns true if merged, false if not yet merged, throws on API error.
 */
export function isPrMerged(url: string, githubToken: string): boolean {
  const coords = parsePrUrl(url);
  if (!coords) throw new Error(`Cannot parse PR URL: ${url}`);

  const { owner, repo, pullNumber } = coords;
  const apiUrl = `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}`;
  const pr = curlJson([
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    apiUrl,
  ]) as GitHubPr;

  return pr.merged_at !== null && pr.merged_at !== undefined;
}

/**
 * Attempt to squash-merge the workspace feature PR (feature/{id} → main).
 * Emits one of: workspace_feature_pr_merged, workspace_feature_pr_merge_failed,
 * workspace_feature_pr_not_mergeable, workspace_feature_pr_url_missing.
 */
function autoMergeWorkspacePr(
  prUrl: string | null | undefined,
  githubToken: string,
  featureId: string,
  emit: (event: Record<string, unknown>) => void,
): void {
  if (!prUrl) {
    emit({ type: "workspace_feature_pr_url_missing", feature_id: featureId });
    return;
  }

  const coords = parsePrUrl(prUrl);
  if (!coords) {
    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: "Cannot parse PR URL" });
    return;
  }

  const { owner, repo, pullNumber } = coords;

  // Check mergeability before attempting merge
  let pr: GitHubPr;
  try {
    pr = curlJson([
      "-s",
      "-H", `Authorization: token ${githubToken}`,
      "-H", "Accept: application/vnd.github+json",
      `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}`,
    ]) as GitHubPr;
  } catch (e) {
    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: String(e) });
    return;
  }

  // mergeable: false → conflicting; skip and let operator resolve
  if (pr.mergeable === false) {
    emit({ type: "workspace_feature_pr_not_mergeable", feature_id: featureId, pr_url: prUrl });
    return;
  }

  // Draft PRs cannot be merged — promote to ready-for-review first.
  if (pr.draft) {
    const promoted = markPrReadyForReview(prUrl, githubToken);
    if (!promoted) {
      emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: "PR is a draft and could not be promoted to ready-for-review" });
      return;
    }
    emit({ type: "workspace_feature_pr_undrafted", feature_id: featureId, pr_url: prUrl });
  }

  // mergeable: true or null (GitHub still computing) → attempt merge
  try {
    const mergeResult = curlJson([
      "-s", "-X", "PUT",
      "-H", `Authorization: token ${githubToken}`,
      "-H", "Accept: application/vnd.github+json",
      "-H", "Content-Type: application/json",
      "-d", JSON.stringify({ merge_method: "squash" }),
      `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}/merge`,
    ]) as { merged?: boolean; message?: string };

    if (mergeResult.merged === true) {
      emit({ type: "workspace_feature_pr_merged", feature_id: featureId, pr_url: prUrl });
    } else {
      emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: mergeResult.message ?? "unknown" });
    }
  } catch (e) {
    emit({ type: "workspace_feature_pr_merge_failed", feature_id: featureId, pr_url: prUrl, details: String(e) });
  }
}

// ── Main export ───────────────────────────────────────────────────────────────

/**
 * Check all `in_handoff` features in the workspace and transition any that
 * have all PRs merged to `feature_status: done`.
 */
export async function handleFeatureDone(opts: HandleFeatureDoneOpts): Promise<void> {
  const {
    workspaceRoot,
    githubToken,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  if (!githubToken) {
    emit({ type: "feature_done_check_skipped", reason: "no_github_token" });
    return;
  }

  const featureIds = listFeatureIds(workspaceRoot);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  for (const featureId of featureIds) {
    const statusYaml = readStatusYaml(workspaceRoot, featureId);

    if (statusYaml.feature_status !== "in_handoff") continue;

    const handoffPrUrl = statusYaml.handoff_pr_url ?? null;
    const implFeaturePrs: ImplFeaturePr[] = Array.isArray(statusYaml.impl_feature_prs)
      ? statusYaml.impl_feature_prs
      : [];

    // Determine which PRs to check
    const implPrsAbsentOrEmpty = implFeaturePrs.length === 0;
    if (implPrsAbsentOrEmpty) {
      emit({ type: "impl_feature_prs_missing", feature_id: featureId });
    }

    if (!handoffPrUrl) {
      emit({ type: "feature_done_check_skipped", feature_id: featureId, reason: "no_handoff_pr_url" });
      continue;
    }

    // Check each PR for merge state
    let allMerged = true;
    const updatedImplPrs = [...implFeaturePrs];

    // Check handoff (management repo) PR
    try {
      const handoffMerged = isPrMerged(handoffPrUrl, githubToken);
      if (!handoffMerged) {
        allMerged = false;
      }
    } catch (e) {
      emit({ type: "feature_done_check_failed", feature_id: featureId, pr_url: handoffPrUrl, details: String(e) });
      continue;
    }

    // Check impl repo PRs (unless absent — already handled above)
    if (!implPrsAbsentOrEmpty) {
      for (let i = 0; i < updatedImplPrs.length; i++) {
        const entry = updatedImplPrs[i];
        try {
          const merged = isPrMerged(entry.url, githubToken);
          if (merged) {
            updatedImplPrs[i] = { ...entry, status: "merged" };
          } else {
            allMerged = false;
          }
        } catch (e) {
          emit({ type: "feature_done_check_failed", feature_id: featureId, pr_url: entry.url, details: String(e) });
          allMerged = false;
          break;
        }
      }
    }

    if (!allMerged) continue;

    // All PRs merged — transition to done
    try {
      // Checkout feature branch to commit status.yaml update
      const featureBranch = featureBranchName(featureId);
      execSync(`git fetch origin`, { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 60_000 });
      execSync(
        `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
        { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
      );

      // Re-read status.yaml after checkout to get latest state
      const freshStatus = readStatusYaml(workspaceRoot, featureId);

      // Idempotency guard — already done
      if (freshStatus.feature_status === "done") {
        emit({ type: "feature_done_already", feature_id: featureId });
        continue;
      }

      // Write updated status.yaml
      freshStatus.feature_status = "done";
      freshStatus.current_stage = "done";
      if (!implPrsAbsentOrEmpty) {
        freshStatus.impl_feature_prs = updatedImplPrs;
      }

      const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
      writeFileSync(statusPath, yamlStringify(freshStatus), "utf-8");

      const statusRel = statusYamlRelPath(featureId);
      execSync(`git add "${statusRel}"`, { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 10_000 });
      try {
        execSync(
          `git commit -m "chore(${featureId}): feature_status → done — all PRs merged"`,
          { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
        );
      } catch (e) {
        const stderr = (e as { stderr?: string }).stderr ?? String(e);
        if (!stderr.includes("nothing to commit")) throw e;
      }

      const pushResult = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
        env,
        encoding: "utf-8",
      });
      if (pushResult.status !== 0) {
        emit({
          type: "feature_done_push_failed",
          feature_id: featureId,
          details: pushResult.stderr,
        });
        continue;
      }

      // Auto-merge the workspace feature PR (feature/{id} → main)
      autoMergeWorkspacePr(freshStatus.workspace_feature_pr_url, githubToken, featureId, emit);

      emit({ type: "feature_done", feature_id: featureId, handoff_pr_url: handoffPrUrl });
    } catch (e) {
      emit({ type: "feature_done_check_failed", feature_id: featureId, details: String(e) });
    }
  }
}

