/**
 * Build a NotificationPort for a given workspace root.
 * Returns a ThreadedSlackNotifier when SLACK_BOT_TOKEN, REDIS_URL, and
 * notifications.slack.channel_id are all present; returns a NullNotifier otherwise.
 */
function buildWorkspaceNotificationPort(
  workspaceRoot: string,
  workspaceId: string,
  emit: (event: Record<string, unknown>) => void,
): NotificationPort {
  const botToken = process.env["SLACK_BOT_TOKEN"];
  const redisUrl = process.env["REDIS_URL"];
  const notifConfig = loadWorkspaceNotificationConfig(workspaceRoot);
  const channelId = notifConfig?.slack.channelId;

  if (!botToken || !redisUrl || !channelId) {
    return new NullNotifier();
  }

  const slack = createSlackWebApiClient(botToken, channelId);
  const store = buildRedisThreadStore();
  const service = new ThreadedNotificationService({
    slack,
    store,
    workspaceId,
    emit: (e) => emit(e as Record<string, unknown>),
  });
  return new ThreadedSlackNotifier(service);
}

