/**
 * Tests for poll/handle-feature-done.ts (T4 — Feature Done Watcher)
 *
 * Covers:
 *   1. All PRs merged → feature_status: done committed and pushed; emits feature_done
 *   2. One impl PR still open → no-op (stays in_handoff)
 *   3. impl_feature_prs absent → emits impl_feature_prs_missing; checks only handoff_pr_url
 *   4. impl_feature_prs empty array → same as absent (emit + handoff-only check)
 *   5. GitHub API error on handoff PR → emits feature_done_check_failed; continues (non-fatal)
 *   6. GitHub API error on impl PR → emits feature_done_check_failed; continues (non-fatal)
 *   7. feature_status not in_handoff → skipped entirely
 *   8. No handoff_pr_url → emits feature_done_check_skipped; continues
 *   9. Already done (idempotency guard) → emits feature_done_already; no second commit
 *  10. No githubToken → emits feature_done_check_skipped; no API calls
 *  11. current_stage: done written alongside feature_status: done (T4)
 *  12. Auto-merge success → emits workspace_feature_pr_merged (T4)
 *  13. workspace_feature_pr_url missing/null → emits workspace_feature_pr_url_missing (T4)
 *  14. CONFLICTING (mergeable: false) → emits workspace_feature_pr_not_mergeable; no merge attempt (T4)
 *  15. mergeable: null (GitHub computing) → proceeds with merge attempt (T4)
 *  16. PUT /merge returns merged: false → emits workspace_feature_pr_merge_failed (T4)
 *  17. Draft workspace PR + undraft succeeds → emits workspace_feature_pr_undrafted then workspace_feature_pr_merged
 *  18. Draft workspace PR + undraft fails → emits workspace_feature_pr_merge_failed; merge not attempted
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";

// ── Mocks ─────────────────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

vi.mock("../src/utils/curl-json.js", () => ({
  curlJson: vi.fn(),
}));

import { execSync, spawnSync } from "node:child_process";
import { curlJson } from "../src/utils/curl-json.js";
import { handleFeatureDone, type HandleFeatureDoneOpts } from "../src/poll/handle-feature-done.js";

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-done-watcher-feature";
const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
const GITHUB_TOKEN = "ghp_test_token";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Agent Test";

const HANDOFF_PR_URL = "https://github.com/test-owner/test-repo/pull/99";
const IMPL_PR_URL_1 = "https://github.com/test-owner/agent-workflow/pull/50";
const IMPL_PR_URL_2 = "https://github.com/test-owner/agent-workflow/pull/51";
const WORKSPACE_PR_URL = "https://github.com/test-owner/test-repo/pull/200";

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "feature-done-watcher-"));
  tmpDirs.push(dir);
  const featureDir = join(dir, "docs", "features", featureId);
  mkdirSync(featureDir, { recursive: true });
  return dir;
}

function writeStatusYaml(wsRoot: string, status: Record<string, unknown>, featureId = FEATURE_ID): void {
  const featureDir = join(wsRoot, "docs", "features", featureId);
  mkdirSync(featureDir, { recursive: true });
  writeFileSync(join(featureDir, "status.yaml"), yamlStringify(status), "utf-8");
}

function readStatusYaml(wsRoot: string, featureId = FEATURE_ID): Record<string, unknown> {
  return parseYaml(
    readFileSync(join(wsRoot, "docs", "features", featureId, "status.yaml"), "utf-8"),
  ) as Record<string, unknown>;
}

function mockGitSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "",
    stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockGitPushFailure(stderr = "fatal: push rejected"): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "",
    stderr, status: 1, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function makeOpts(wsRoot: string, overrides: Partial<HandleFeatureDoneOpts> = {}): HandleFeatureDoneOpts {
  return {
    workspaceRoot: wsRoot,
    githubToken: GITHUB_TOKEN,
    gitAuthorEmail: GIT_AUTHOR_EMAIL,
    gitAuthorName: GIT_AUTHOR_NAME,
    sshKeyPath: undefined,
    emit: () => {},
    ...overrides,
  };
}

function makeInHandoffStatus(extra: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    feature_id: FEATURE_ID,
    feature_status: "in_handoff",
    handoff_pr_url: HANDOFF_PR_URL,
    impl_feature_prs: [
      { repo: "workflow", url: IMPL_PR_URL_1, status: "open" },
    ],
    ...extra,
  };
}

// ── Mock GitHub API response helpers ──────────────────────────────────────────

function mockPrMerged(): Record<string, unknown> {
  return { merged_at: "2026-05-09T10:00:00Z", state: "closed" };
}

function mockPrOpen(): Record<string, unknown> {
  return { merged_at: null, state: "open" };
}

function mockPrOpenMergeable(mergeable: boolean | null): Record<string, unknown> {
  return { merged_at: null, state: "open", mergeable };
}

function mockMergeSuccess(): Record<string, unknown> {
  return { merged: true, message: "Pull Request successfully merged" };
}

function mockMergeFailure(message = "Not mergeable"): Record<string, unknown> {
  return { merged: false, message };
}

function mockPrDraft(mergeable: boolean | null): Record<string, unknown> {
  return { merged_at: null, state: "open", draft: true, mergeable };
}

function mockGqlPrQueryDraft(): Record<string, unknown> {
  return {
    data: {
      repository: {
        pullRequest: {
          id: "PR_kwTest",
          isDraft: true,
          state: "OPEN",
          url: WORKSPACE_PR_URL,
        },
      },
    },
  };
}

function mockGqlMarkReadySuccess(): Record<string, unknown> {
  return {
    data: {
      markPullRequestReadyForReview: {
        pullRequest: { id: "PR_kwTest", isDraft: false, url: WORKSPACE_PR_URL },
      },
    },
  };
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.resetAllMocks();
});

// ── Tests ──────────────────────────────────────────────────────────────────────

describe("handleFeatureDone — all PRs merged", () => {
  it("transitions feature_status to done and emits feature_done", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    vi.mocked(curlJson).mockReturnValue(mockPrMerged());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // status.yaml on disk should now be done
    const status = readStatusYaml(wsRoot);
    expect(status.feature_status).toBe("done");

    // impl_feature_prs status updated to merged
    const implPrs = status.impl_feature_prs as Array<{ status: string }>;
    expect(implPrs[0].status).toBe("merged");

    // feature_done emitted
    expect(events.some((e) => e.type === "feature_done" && e.feature_id === FEATURE_ID)).toBe(true);
  });

  it("commits status.yaml with correct message", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    vi.mocked(curlJson).mockReturnValue(mockPrMerged());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    await handleFeatureDone(makeOpts(wsRoot));

    // Should have called git commit
    const commitCall = vi.mocked(execSync).mock.calls.find((args) =>
      String(args[0]).includes("git commit")
    );
    expect(commitCall).toBeDefined();
    expect(String(commitCall![0])).toContain("feature_status → done");

    // Should have called git push with the feature branch
    const pushCall = vi.mocked(spawnSync).mock.calls.find(
      (args) => args[0] === "git" && Array.isArray(args[1]) && (args[1] as string[]).includes(FEATURE_BRANCH),
    );
    expect(pushCall).toBeDefined();
  });
});

describe("handleFeatureDone — one impl PR still open", () => {
  it("does not transition to done and does not commit", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({
      impl_feature_prs: [
        { repo: "workflow", url: IMPL_PR_URL_1, status: "open" },
        { repo: "workflow", url: IMPL_PR_URL_2, status: "open" },
      ],
    }));

    // handoff PR merged, impl PR 1 merged, impl PR 2 still open
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())  // handoff_pr_url
      .mockReturnValueOnce(mockPrMerged())  // IMPL_PR_URL_1
      .mockReturnValueOnce(mockPrOpen());   // IMPL_PR_URL_2

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // feature_done should NOT be emitted
    expect(events.some((e) => e.type === "feature_done")).toBe(false);

    // status.yaml should remain in_handoff
    const status = readStatusYaml(wsRoot);
    expect(status.feature_status).toBe("in_handoff");

    // No git commit should have been made
    expect(vi.mocked(execSync).mock.calls.some((args) =>
      String(args[0]).includes("git commit")
    )).toBe(false);
  });
});

describe("handleFeatureDone — impl_feature_prs absent", () => {
