describe("handleFeatureDone — GitHub API error (non-fatal)", () => {
  it("emits feature_done_check_failed on handoff PR API error and continues", async () => {
    const wsRoot = makeWorkspace();
    // Two features: first one will error, second should still be processed
    const featureId2 = "test-done-watcher-feature-2";
    makeWorkspace(featureId2);
    writeStatusYaml(wsRoot, makeInHandoffStatus());
    // Write a second feature dir
    const dir2 = join(wsRoot, "docs", "features", featureId2);
    mkdirSync(dir2, { recursive: true });
    writeFileSync(
      join(dir2, "status.yaml"),
      yamlStringify({ feature_status: "in_handoff", handoff_pr_url: HANDOFF_PR_URL }),
      "utf-8",
    );

    vi.mocked(curlJson)
      .mockImplementationOnce(() => { throw new Error("API rate limited"); })  // feature 1 handoff PR error
      .mockReturnValue(mockPrMerged());  // feature 2 calls succeed

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // feature_done_check_failed emitted for feature 1
    expect(events.some((e) => e.type === "feature_done_check_failed")).toBe(true);

    // feature 1 should still be in_handoff
    const status1 = readStatusYaml(wsRoot, FEATURE_ID);
    expect(status1.feature_status).toBe("in_handoff");
  });

  it("emits feature_done_check_failed on impl PR API error and skips (non-fatal)", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())              // handoff PR OK
      .mockImplementationOnce(() => { throw new Error("network error"); }); // impl PR error

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "feature_done_check_failed" && e.feature_id === FEATURE_ID)).toBe(true);

    // Should NOT transition to done since impl PR check failed
    const status = readStatusYaml(wsRoot);
    expect(status.feature_status).toBe("in_handoff");
  });
});

describe("handleFeatureDone — feature_status not in_handoff", () => {
