describe("handleFeatureDone — reads status.yaml via git show (feature branch)", () => {
  it("uses git show origin/<featureBranch>:... to read status when available (not local FS)", async () => {
    const wsRoot = makeWorkspace();
    // Local FS has in_implementation — would be skipped if read directly
    writeStatusYaml(wsRoot, {
      feature_id: FEATURE_ID,
      feature_status: "in_implementation",
      handoff_pr_url: null,
    });

    // git show returns in_handoff from the feature branch
    const featureBranchStatus = {
      feature_id: FEATURE_ID,
