    };
    const { stringify: yamlStringifyLocal } = await import("yaml");

    vi.mocked(execSync).mockImplementation((cmd) => {
      if (String(cmd).includes(" show ") && String(cmd).includes("origin/feature/")) {
        return yamlStringifyLocal(featureBranchStatus) as unknown as Buffer;
      }
      return undefined as unknown as Buffer;
    });

    vi.mocked(curlJson).mockReturnValue(mockPrMerged());

    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // Should have read in_handoff from git show — not skipped
    expect(vi.mocked(curlJson)).toHaveBeenCalled();
  });
});

