describe("handleFeatureDone — idempotency", () => {
  it("emits feature_done_already and skips commit if already done after checkout", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    // curlJson says both PRs merged
    vi.mocked(curlJson).mockReturnValue(mockPrMerged());

    // After git checkout -B, execSync will be called. We simulate the status.yaml
    // on disk being already `done` by overwriting it in a mock side-effect.
    let checkoutCalled = false;
    vi.mocked(execSync).mockImplementation((cmd) => {
      if (String(cmd).includes("checkout -B") && !checkoutCalled) {
        checkoutCalled = true;
        // Simulate: after checkout, status.yaml already shows done
        writeStatusYaml(wsRoot, {
          ...makeInHandoffStatus(),
          feature_status: "done",
        });
      }
      return undefined as unknown as Buffer;
    });

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // Should emit feature_done_already
    expect(events.some((e) => e.type === "feature_done_already" && e.feature_id === FEATURE_ID)).toBe(true);
    // Should NOT emit feature_done
    expect(events.some((e) => e.type === "feature_done")).toBe(false);
    // No commit
    expect(vi.mocked(execSync).mock.calls.some((args) =>
      String(args[0]).includes("git commit")
    )).toBe(false);
  });
});

