describe("handleFeatureDone — auto-merge workspace PR (T4)", () => {
  it("emits workspace_feature_pr_merged when auto-merge succeeds", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())            // handoff PR check
      .mockReturnValueOnce(mockPrMerged())            // impl PR check
      .mockReturnValueOnce(mockPrOpenMergeable(true)) // workspace PR mergeability GET
      .mockReturnValueOnce(mockMergeSuccess());        // PUT /merge

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_merged" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });

  it("emits workspace_feature_pr_url_missing when workspace_feature_pr_url is null", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: null }));

    vi.mocked(curlJson).mockReturnValue(mockPrMerged());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_url_missing" && e.feature_id === FEATURE_ID)).toBe(true);
    // done state still committed and feature_done emitted
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });

  it("emits workspace_feature_pr_not_mergeable and skips merge when mergeable is false (CONFLICTING)", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())              // handoff PR check
      .mockReturnValueOnce(mockPrMerged())              // impl PR check
      .mockReturnValueOnce(mockPrOpenMergeable(false)); // workspace PR: CONFLICTING

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_not_mergeable" && e.feature_id === FEATURE_ID)).toBe(true);
    // No PUT /merge call — only 3 curlJson calls total (handoff + impl + mergeability check)
    expect(vi.mocked(curlJson).mock.calls.length).toBe(3);
    // done state still committed
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });

  it("proceeds with auto-merge attempt when mergeable is null (GitHub still computing)", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())             // handoff PR check
      .mockReturnValueOnce(mockPrMerged())             // impl PR check
      .mockReturnValueOnce(mockPrOpenMergeable(null))  // workspace PR: null (still computing)
      .mockReturnValueOnce(mockMergeSuccess());         // PUT /merge

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // Should attempt the merge (not skip)
    expect(events.some((e) => e.type === "workspace_feature_pr_merged")).toBe(true);
    expect(events.some((e) => e.type === "workspace_feature_pr_not_mergeable")).toBe(false);
  });

  it("emits workspace_feature_pr_merge_failed when PUT /merge returns merged: false", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())             // handoff PR check
      .mockReturnValueOnce(mockPrMerged())             // impl PR check
      .mockReturnValueOnce(mockPrOpenMergeable(true))  // workspace PR: mergeable
      .mockReturnValueOnce(mockMergeFailure());         // PUT /merge: not merged

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_merge_failed" && e.feature_id === FEATURE_ID)).toBe(true);
    // done state still committed despite merge failure
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });

  it("undrafts a draft workspace PR before merging and emits workspace_feature_pr_undrafted", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())            // handoff PR check
      .mockReturnValueOnce(mockPrMerged())            // impl PR check
      .mockReturnValueOnce(mockPrDraft(true))         // workspace PR GET: draft + mergeable
      .mockReturnValueOnce(mockGqlPrQueryDraft())     // GraphQL query: isDraft=true
      .mockReturnValueOnce(mockGqlMarkReadySuccess()) // GraphQL mutation: mark ready
      .mockReturnValueOnce(mockMergeSuccess());       // PUT /merge

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_undrafted" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "workspace_feature_pr_merged" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });

  it("emits workspace_feature_pr_merge_failed and skips merge when undraft fails", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ workspace_feature_pr_url: WORKSPACE_PR_URL }));

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockPrMerged())  // handoff PR check
      .mockReturnValueOnce(mockPrMerged())  // impl PR check
      .mockReturnValueOnce(mockPrDraft(true)) // workspace PR GET: draft + mergeable
      .mockImplementationOnce(() => { throw new Error("GraphQL API error"); }); // GraphQL query throws → markPrReadyForReview returns null

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await handleFeatureDone(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "workspace_feature_pr_merge_failed" && e.feature_id === FEATURE_ID)).toBe(true);
    // Merge must not have been attempted — only 4 curlJson calls (handoff + impl + PR GET + GraphQL that threw)
    expect(vi.mocked(curlJson).mock.calls.length).toBe(4);
    expect(events.some((e) => e.type === "workspace_feature_pr_merged")).toBe(false);
    expect(events.some((e) => e.type === "feature_done")).toBe(true);
  });
});

